<?php
require_once __DIR__ . '/../../config/config.php';
require_roles(['ADMIN','HR']); $pdo=db(); $id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT) ?: null; $employee=$id?phase2_require_employee($pdo,$id):[]; $error=null;
$departments=$pdo->query('SELECT id,name FROM departments WHERE is_active=1 ORDER BY name')->fetchAll(); $positions=$pdo->query('SELECT id,name FROM positions WHERE is_active=1 ORDER BY name')->fetchAll(); $branches=$pdo->query('SELECT id,name FROM branches WHERE is_active=1 ORDER BY name')->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf(); $fields=['employee_number','first_name','middle_name','last_name','suffix','date_of_birth','gender','civil_status','nationality','email','phone','address','city','province','postal_code','department_id','position_id','branch_id','employment_status','date_hired','probation_end_date','employment_type']; $data=[]; foreach($fields as $field){$data[$field]=post_value($field); if(in_array($field,['department_id','position_id','branch_id'],true))$data[$field]=(int)$data[$field]?:null;} if(!$data['employee_number']||!$data['first_name']||!$data['last_name'])$error='Employee ID, first name, and last name are required.'; else try{$data['employment_status']=$data['employment_status']?:'Active';$data['employment_type']=$data['employment_type']?:'Regular';$data['date_of_birth']=valid_date($data['date_of_birth']);$data['date_hired']=valid_date($data['date_hired']);$data['probation_end_date']=valid_date($data['probation_end_date']);$columns=implode(',',array_keys($data));$marks=implode(',',array_fill(0,count($data),'?'));if($id){$set=implode(',',array_map(fn($field)=>$field.'=?',array_keys($data)));$pdo->prepare("UPDATE employees SET $set WHERE id=?")->execute([...array_values($data),$id]);audit('UPDATE','employees',$id);flash('success','Employee updated.');}else{$pdo->prepare("INSERT INTO employees ($columns) VALUES ($marks)")->execute(array_values($data));$id=(int)$pdo->lastInsertId();audit('CREATE','employees',$id);flash('success','Employee created.');}redirect('admin/employees/view.php?id='.$id);}catch(PDOException $exception){$error='Unable to save employee. Check unique ID/email and valid dates.';}}
$pageTitle=$id?'Edit employee':'Add employee';require __DIR__.'/../../includes/header.php';?><div class="mb-6"><a href="index.php" class="text-sm font-bold text-teal-700">← Employees</a><h1 class="font-display text-3xl font-bold mt-2"><?=e($pageTitle)?></h1></div><?php if($error):?><div class="mb-5 rounded-lg bg-red-50 border border-red-200 p-3 text-sm text-red-700"><?=e($error)?></div><?php endif;?><form method="post" class="bg-white border border-slate-200 rounded-xl p-6"><?= csrf_field() ?><div class="grid md:grid-cols-3 gap-4"><h2 class="md:col-span-3 font-display text-xl font-bold">Personal information</h2><?php foreach(['employee_number'=>'Employee ID','first_name'=>'First name','middle_name'=>'Middle name','last_name'=>'Last name','suffix'=>'Suffix','date_of_birth'=>'Date of birth','nationality'=>'Nationality','email'=>'Email','phone'=>'Phone','address'=>'Address','city'=>'City','province'=>'Province','postal_code'=>'Postal code'] as $field=>$label):?><label class="text-sm font-semibold"><?=e($label)?><input <?=str_contains($field,'date')?'type="date"':''?> <?=in_array($field,['employee_number','first_name','last_name'],true)?'required':''?> name="<?=e($field)?>" value="<?=e($employee[$field]??$_POST[$field]??'')?>" class="field"></label><?php endforeach;?><label class="text-sm font-semibold">Gender<select name="gender" class="field"><option value="">Select</option><?php foreach(['Female','Male','Non-binary','Prefer not to say'] as $v):?><option <?=($employee['gender']??$_POST['gender']??'')===$v?'selected':''?>><?=e($v)?></option><?php endforeach;?></select></label><label class="text-sm font-semibold">Civil status<select name="civil_status" class="field"><option value="">Select</option><?php foreach(['Single','Married','Widowed','Separated'] as $v):?><option <?=($employee['civil_status']??$_POST['civil_status']??'')===$v?'selected':''?>><?=e($v)?></option><?php endforeach;?></select></label><h2 class="md:col-span-3 font-display text-xl font-bold mt-4">Employment information</h2><?php foreach(['department_id'=>'Department','position_id'=>'Position','branch_id'=>'Branch'] as $field=>$label):?><label class="text-sm font-semibold"><?=e($label)?><select name="<?=e($field)?>" class="field"><option value="">Select</option><?php $items=$field==='department_id'?$departments:($field==='position_id'?$positions:$branches);foreach($items as $item):?><option value="<?=e($item['id'])?>" <?=((string)($employee[$field]??$_POST[$field]??''))===(string)$item['id']?'selected':''?>><?=e($item['name'])?></option><?php endforeach;?></select></label><?php endforeach;?><label class="text-sm font-semibold">Employment status<select name="employment_status" class="field"><?php foreach(['Active','Probationary','On Leave','Separated'] as $v):?><option <?=($employee['employment_status']??$_POST['employment_status']??'Active')===$v?'selected':''?>><?=e($v)?></option><?php endforeach;?></select></label><label class="text-sm font-semibold">Date hired<input type="date" name="date_hired" value="<?=e($employee['date_hired']??$_POST['date_hired']??'')?>" class="field"></label><label class="text-sm font-semibold">Probation end date<input type="date" name="probation_end_date" value="<?=e($employee['probation_end_date']??$_POST['probation_end_date']??'')?>" class="field"></label><label class="text-sm font-semibold">Employment type<select name="employment_type" class="field"><?php foreach(['Regular','Probationary','Contractual','Part-time'] as $v):?><option <?=($employee['employment_type']??$_POST['employment_type']??'Regular')===$v?'selected':''?>><?=e($v)?></option><?php endforeach;?></select></label></div><div class="mt-7 flex justify-end gap-3"><a href="index.php" class="rounded-lg border px-5 py-3 font-bold text-sm">Cancel</a><button class="rounded-lg bg-teal-700 px-5 py-3 font-bold text-sm text-white">Save employee</button></div></form><?php require __DIR__.'/../../includes/footer.php';